<main class="wrap">
  <h1>Szókártyák</h1>
  <p class="subtitle">Kattints egy kártyára, hogy megforduljon, és nézd meg a magyar szót!</p>

  <div class="scoreboard">
    <div class="stat"><span class="stat-label">Összes pont</span><span class="stat-value" id="score">0</span></div>
    <div class="stat"><span class="stat-label">Bevett szavak</span><span class="stat-value" id="learned">0</span></div>
    <div class="stat"><span class="stat-label">Ez a kör</span><span class="stat-value" id="turns">0</span></div>
  </div>

  <span class="cat-label" id="catLabel">Válassz témát</span>
  <div class="cats" id="cats" role="group" aria-labelledby="catLabel"></div>

  <div class="grid" id="grid" aria-live="polite"></div>

  <div class="toolbar">
    <button class="btn" id="shuffle" type="button">Új keverés</button>
    <button class="btn danger" id="reset" type="button">Pontok törlése</button>
    <span class="confirm" id="confirm">
      <button class="btn danger" id="confirmYes" type="button">Igen, töröljem</button>
      <button class="btn" id="confirmNo" type="button">Mégse</button>
    </span>
  </div>

  <p class="sr-only" id="status" aria-live="polite"></p>
</main>
<script>
  const WORDS = [
    {cat:'allatok', en:'cat', hu:'macska', emoji:'🐱'},
    {cat:'allatok', en:'dog', hu:'kutya', emoji:'🐶'},
    {cat:'allatok', en:'bird', hu:'madár', emoji:'🐦'},
    {cat:'allatok', en:'fish', hu:'hal', emoji:'🐟'},
    {cat:'allatok', en:'horse', hu:'ló', emoji:'🐴'},
    {cat:'allatok', en:'pig', hu:'malac', emoji:'🐷'},
    {cat:'allatok', en:'cow', hu:'tehén', emoji:'🐄'},
    {cat:'allatok', en:'sheep', hu:'juh', emoji:'🐑'},
    {cat:'allatok', en:'rabbit', hu:'nyúl', emoji:'🐰'},
    {cat:'allatok', en:'lion', hu:'oroszlán', emoji:'🦁'},
    {cat:'allatok', en:'tiger', hu:'tigrist', emoji:'🐯'},
    {cat:'allatok', en:'bear', hu:'medve', emoji:'🐻'},
    {cat:'szinek', en:'red', hu:'piros', emoji:'🔴'},
    {cat:'szinek', en:'blue', hu:'kék', emoji:'🔵'},
    {cat:'szinek', en:'green', hu:'zöld', emoji:'🟢'},
    {cat:'szinek', en:'yellow', hu:'sárga', emoji:'🟡'},
    {cat:'szinek', en:'orange', hu:'narancs', emoji:'🟠'},
    {cat:'szinek', en:'purple', hu:'lila', emoji:'🟣'},
    {cat:'szinek', en:'pink', hu:'rózsaszín', emoji:'🌸'},
    {cat:'szinek', en:'brown', hu:'barna', emoji:'🟤'},
    {cat:'szinek', en:'black', hu:'fekete', emoji:'⚫'},
    {cat:'szinek', en:'white', hu:'fehér', emoji:'⚪'},
    {cat:'szinek', en:'gray', hu:'szürke', emoji:'🌫️'},
    {cat:'iskola', en:'book', hu:'könyv', emoji:'📖'},
    {cat:'iskola', en:'pencil', hu:'ceruza', emoji:'✏️'},
    {cat:'iskola', en:'pen', hu:'toll', emoji:'🖊️'},
    {cat:'iskola', en:'ruler', hu:'vonalzó', emoji:'📏'},
    {cat:'iskola', en:'bag', hu:'táska', emoji:'🎒'},
    {cat:'iskola', en:'scissors', hu:'olló', emoji:'✂️'},
    {cat:'iskola', en:'paper', hu:'papír', emoji:'📄'},
    {cat:'iskola', en:'clock', hu:'óra', emoji:'⏰'},
    {cat:'iskola', en:'chair', hu:'szék', emoji:'🪑'},
    {cat:'iskola', en:'apple', hu:'alma', emoji:'🍎'}
  ];
  const CATS = [
    {id:'allatok', label:'Állatok'},
    {id:'szinek', label:'Színek'},
    {id:'iskola', label:'Iskola'}
  ];

  const KEY = 'cards-v1';
  const hasStorage = !!(window.alfy && window.alfy.storage);
  let state = { score:0, learned:{}, cat:'allatok' };
  let current = [];

  const grid = document.getElementById('grid');
  const cats = document.getElementById('cats');
  const scoreEl = document.getElementById('score');
  const learnedEl = document.getElementById('learned');
  const turnsEl = document.getElementById('turns');
  const statusEl = document.getElementById('status');
  const confirmBox = document.getElementById('confirm');

  function save() {
    if (hasStorage) { window.alfy.storage.set(KEY, state).catch(function(){}); }
  }

  function announce(msg) { statusEl.textContent = msg; }

  function renderCats() {
    cats.innerHTML = '';
    CATS.forEach(function(c) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip' + (state.cat === c.id ? ' active' : '');
      b.textContent = c.label;
      b.setAttribute('aria-pressed', state.cat === c.id ? 'true' : 'false');
      b.addEventListener('click', function() {
        state.cat = c.id;
        renderCats();
        buildDeck();
      });
      cats.appendChild(b);
    });
  }

  function updateStats() {
    const learnedCount = Object.keys(state.learned).length;
    scoreEl.textContent = state.score;
    learnedEl.textContent = learnedCount;
  }

  function buildDeck() {
    const pool = WORDS.filter(function(w) { return w.cat === state.cat; });
    const deck = pool.slice();
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = deck[i]; deck[i] = deck[j]; deck[j] = t;
    }
    current = deck;
    turnsEl.textContent = '0';
    renderCards();
  }

  function renderCards() {
    grid.innerHTML = '';
    current.forEach(function(w, idx) {
      const card = document.createElement('div');
      card.className = 'card' + (state.learned[w.en] ? ' learned' : '');
      const inner = document.createElement('div');
      inner.className = 'card-inner';

      const front = document.createElement('div');
      front.className = 'face face-front';
      front.innerHTML = '<span class="emoji">' + w.emoji + '</span>' +
        '<span class="word">' + w.en + '</span>' +
        '<span class="hint">Kattints a fordításért</span>';

      const back = document.createElement('div');
      back.className = 'face face-back';
      back.innerHTML = '<span class="emoji">' + w.emoji + '</span>' +
        '<span class="word">' + w.hu + '</span>' +
        '<span class="hint">' + w.en + ' = ' + w.hu + '</span>' +
        (state.learned[w.en] ? '<span class="badge">✓ Bevetted</span>' : '');

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card-btn';
      btn.setAttribute('aria-label', w.en + ' – kattints a magyar szóért');
      btn.addEventListener('click', function() {
        const wasLearned = !!state.learned[w.en];
        card.classList.add('flipped');
        if (!wasLearned) {
          state.learned[w.en] = true;
          state.score += 10;
          updateStats();
          save();
          back.innerHTML = '<span class="emoji">' + w.emoji + '</span>' +
            '<span class="word">' + w.hu + '</span>' +
            '<span class="hint">' + w.en + ' = ' + w.hu + '</span>' +
            '<span class="badge">✓ Bevetted</span>';
          card.classList.add('learned');
          announce('Bevetted: ' + w.en + ' = ' + w.hu + '. Pont: ' + state.score);
        }
        const t = parseInt(turnsEl.textContent, 10) + 1;
        turnsEl.textContent = t;
      });

      inner.appendChild(front);
      inner.appendChild(back);
      card.appendChild(btn);
      grid.appendChild(card);
    });
  }

  document.getElementById('shuffle').addEventListener('click', function() {
    buildDeck();
    announce('Új kártyák keverve.');
  });

  document.getElementById('reset').addEventListener('click', function() {
    confirmBox.classList.add('show');
  });
  document.getElementById('confirmNo').addEventListener('click', function() {
    confirmBox.classList.remove('show');
  });
  document.getElementById('confirmYes').addEventListener('click', function() {
    state.score = 0;
    state.learned = {};
    updateStats();
    save();
    buildDeck();
    confirmBox.classList.remove('show');
    announce('Pontok törölve.');
  });

  async function init() {
    if (hasStorage) {
      try {
        const saved = await window.alfy.storage.get(KEY);
        if (saved && typeof saved === 'object') {
          state.score = Number(saved.score) || 0;
          state.learned = (saved.learned && typeof saved.learned === 'object') ? saved.learned : {};
          state.cat = CATS.some(function(c) { return c.id === saved.cat; }) ? saved.cat : 'allatok';
        }
      } catch (e) {}
    }
    renderCats();
    updateStats();
    buildDeck();
  }

  init();
</script>
</body>
</html>
